#!/usr/bin/python3
from pwn import *

def receive_question(conn):
    return conn.recvuntil(b'Please enter your answer: ').decode()

def main():
    # Connect to the remote server
    conn = remote('forensics.chal.csaw.io', 5000)

    # Get the first question
    question = receive_question(conn)
    print("Question received:", question)

    # For analyzing the date, let's try answering the first question to see more context
    # The answer doesn't matter for now as we just want to see the next questions
    conn.sendline(b"unknown")
    try:
        next_question = receive_question(conn)
        print("Next question:", next_question)
    except:
        print("Connection ended")

    conn.close()

if __name__ == "__main__":
    main()

